function readIdea(query) {
  const raw = query?.query;
  if (typeof raw !== "string") return { valid: false, idea: "" };
  const idea = raw.trim();
  const invalid =
    !idea ||
    idea.length > 2000 ||
    Array.from(idea).length > 1000 ||
    /[\u0000-\u0008\u000b-\u000c\u000e-\u001f\u007f]/u.test(idea);
  return { valid: !invalid, idea: invalid ? "" : idea };
}

return { json: readIdea($json.query) };

function escapeHtml(text) {
  return text.replace(
    /[&<>"']/g,
    (character) =>
      ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[character],
  );
}

function makePage(title, markup, style, policy, lang = "en") {
  return (
    '<!doctype html>\n<html lang="' +
    escapeHtml(lang) +
    '"><head><meta charset="utf-8">' +
    '<meta http-equiv="Content-Security-Policy" content="' +
    policy +
    '">' +
    '<meta name="viewport" content="width=device-width, initial-scale=1">' +
    "<title>" +
    escapeHtml(title) +
    "</title><style>" +
    style +
    "</style></head><body>" +
    markup +
    "</body></html>"
  );
}

function renderTree(tree, tags) {
  const safeClasses = new Set(["hero", "card", "grid", "stack", "muted"]);
  const inputKinds = new Set([
    "text",
    "email",
    "tel",
    "number",
    "date",
    "checkbox",
    "radio",
    "search",
    "url",
    "password",
  ]);
  const identifier = /^[A-Za-z][A-Za-z0-9_-]{0,63}$/;
  const language = /^[a-z]{2,3}(?:-[a-z0-9]{2,8}){0,2}$/i;
  const allowed = new Set(tags);
  const ids = new Set();
  let title = "";
  let count = 0;
  let lang = "en";

  function component(node, depth) {
    if (
      depth > 8 ||
      ++count > 90 ||
      !node ||
      !allowed.has(node.type) ||
      typeof node.label !== "string" ||
      node.label.length > 600 ||
      !Array.isArray(node.children) ||
      !Array.isArray(node.attributes) ||
      node.attributes.length > 12
    ) {
      throw new Error("Invalid preview component");
    }
    const { type, label } = node;
    const text = escapeHtml(label);
    if (!title && type === "h1" && label.trim())
      title = Array.from(label.trim()).slice(0, 140).join("");

    const attributes = new Map();
    for (const item of node.attributes) {
      const value = item?.value;
      if (typeof value !== "string" || value.length > 240) continue;
      const name = item.name;
      if (name === "class") {
        const classes = [...new Set(value.split(/\s+/).filter((token) => safeClasses.has(token)))];
        if (classes.length) attributes.set(name, classes.join(" "));
      } else if (name === "id" && identifier.test(value) && !ids.has(value)) {
        if (attributes.has("id")) continue;
        attributes.set(name, value);
        ids.add(value);
      } else if (name === "lang" && language.test(value)) {
        attributes.set(name, value);
        if (depth === 0) lang = value;
      } else if (name === "title" || name === "aria-label") {
        attributes.set(name, value);
      } else if (
        type === "a" &&
        name === "href" &&
        value.startsWith("#") &&
        identifier.test(value.slice(1))
      ) {
        attributes.set(name, value);
      } else if (type === "label" && name === "for" && identifier.test(value)) {
        attributes.set(name, value);
      } else if ((type === "textarea" || type === "input") && name === "placeholder") {
        attributes.set(name, value);
      } else if (type === "input" && name === "type" && inputKinds.has(value)) {
        attributes.set(name, value);
      } else if ((type === "th" || type === "td") && name === "colspan" && /^[1-6]$/.test(value)) {
        attributes.set(name, value);
      } else if (type === "img" && name === "alt") {
        attributes.set(name, value);
      }
    }

    if (type === "img") {
      const alt = attributes.get("alt") || label || "Image";
      return (
        '<div class="image-placeholder" role="img" aria-label="' +
        escapeHtml(alt) +
        '">' +
        escapeHtml(alt) +
        "</div>"
      );
    }
    if (
      ["input", "textarea", "select", "button"].includes(type) &&
      label &&
      !attributes.has("aria-label")
    ) {
      attributes.set("aria-label", label);
    }
    if (type === "button") attributes.set("type", "button");
    const attrs = [...attributes]
      .map(([name, value]) => " " + name + '="' + escapeHtml(value) + '"')
      .join("");
    const children = node.children.map((child) => component(child, depth + 1)).join("");
    if (type === "input") return "<input" + attrs + " disabled>";
    if (type === "hr") return "<hr" + attrs + ">";
    if (type === "form")
      return (
        "<fieldset" +
        attrs +
        " disabled>" +
        (text ? "<legend>" + text + "</legend>" : "") +
        children +
        "</fieldset>"
      );
    if (["select", "textarea", "button"].includes(type)) {
      return (
        "<" +
        type +
        attrs +
        " disabled>" +
        (type === "button" ? text : "") +
        (type === "textarea" ? "" : children) +
        "</" +
        type +
        ">"
      );
    }
    return "<" + type + attrs + ">" + text + children + "</" + type + ">";
  }

  const markup = component(tree, 0);
  return { title: title || "Website preview", markup, lang };
}

function modelPreview(response, tags) {
  if (response?.status !== "completed" || response.error || !Array.isArray(response.output))
    throw new Error("Preview response incomplete");
  const content = response.output
    .filter((item) => item?.type === "message" && item.role === "assistant")
    .flatMap((item) => item.content ?? []);
  if (
    content.length !== 1 ||
    content[0].type !== "output_text" ||
    typeof content[0].text !== "string" ||
    content[0].text.length > 45000
  ) {
    throw new Error("Preview response did not contain one UI tree");
  }
  return renderTree(JSON.parse(content[0].text), tags);
}

function previewResponse(valid, model, tags, style, policy) {
  let status = 400;
  let title = "Website idea required";
  let markup =
    "<main><h1>Website idea required</h1><p>Supply one query parameter with a website idea of up to 1,000 characters.</p></main>";
  let lang = "en";
  if (valid) {
    try {
      ({ title, markup, lang } = modelPreview(model, tags));
      status = 200;
    } catch {
      status = 502;
      title = "Preview unavailable";
      markup =
        "<main><h1>Preview unavailable</h1><p>The website preview could not be generated. Try again later.</p></main>";
    }
  }
  return { status, html: makePage(title, markup, style, policy, lang) };
}

const valid = $("Validate the website idea").first().json.valid;
return {
  json: previewResponse(
    valid,
