    "default-src 'none'; script-src 'none'; object-src 'none'; style-src 'sha256-P0u9TZDEU6Tq3TxWjrunWtkDBG3UFEmzKfUquyqdryc='; base-uri 'none'; form-action 'none'",
  ),
